/**
 * sync-artifact [--check]
 *
 * Copies the creation bytecode of the forge-compiled TwokeyEscrow into src/lib/escrowArtifact.ts so the
 * app can deploy EXACTLY the bytes forge produced (explorer verification then matches).
 *
 *   bun run artifact:sync    # forge build first, then regenerate src/lib/escrowArtifact.ts
 *   bun run artifact:check   # exit 1 if the generated file is stale compared with the forge artifact
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { keccak256 } from 'viem'

const ARTIFACT = 'contracts/out/TwokeyEscrow.sol/TwokeyEscrow.json'
const OUTPUT = 'src/lib/escrowArtifact.ts'

interface Artifact {
  bytecode: { object: string }
  metadata?: {
    compiler?: { version?: string }
    settings?: { optimizer?: { enabled?: boolean; runs?: number }; evmVersion?: string }
  }
}

function fail(message: string): never {
  console.error(message)
  process.exit(1)
}

if (!existsSync(ARTIFACT)) fail(`Missing ${ARTIFACT}. Run \`forge build\` first.`)

const artifact = JSON.parse(readFileSync(ARTIFACT, 'utf8')) as Artifact
const bytecode = artifact.bytecode.object
if (!/^0x[0-9a-fA-F]+$/.test(bytecode) || bytecode.includes('__$')) fail('Artifact bytecode is empty or has unlinked libraries.')

const hash = keccak256(bytecode as `0x${string}`)
const solc = artifact.metadata?.compiler?.version ?? 'unknown'
const evm = artifact.metadata?.settings?.evmVersion ?? 'unknown'
const runs = artifact.metadata?.settings?.optimizer?.runs ?? 0

const source = `// Generated by scripts/sync-artifact.ts from ${ARTIFACT}. Do not edit by hand.
// Regenerate with \`forge build && bun run artifact:sync\`.
import type { Hex } from 'viem'

/** Creation bytecode exactly as forge compiled it (constructor arguments are appended at deploy time). */
export const ESCROW_CREATION_BYTECODE: Hex = '${bytecode}'

export const ESCROW_CREATION_BYTECODE_HASH: Hex = '${hash}'

export const ESCROW_BUILD = {
  solc: '${solc}',
  evmVersion: '${evm}',
  optimizerRuns: ${runs},
} as const
`

if (process.argv.includes('--check')) {
  const current = existsSync(OUTPUT) ? readFileSync(OUTPUT, 'utf8') : ''
  if (current !== source) fail(`${OUTPUT} is out of date. Run \`bun run artifact:sync\`.`)
  console.log(`${OUTPUT} matches the forge artifact (${hash}).`)
} else {
  writeFileSync(OUTPUT, source)
  console.log(`Wrote ${OUTPUT} (${(bytecode.length - 2) / 2} bytes, keccak ${hash}).`)
}
